  "Raw Materials": ["Stock below reorder level for the next production run.", "Confirmed customer order needs material by month end.", "Planned build for the Q-end dispatch schedule."],
  Equipment: ["Existing units worn beyond tolerance.", "Required for the new fixture line.", "Replacement for equipment that failed calibration."],
